// Inline icons: Lucide's (ISC license) for features and actions, and the
// platforms' marks from Simple Icons (CC0). Windows' four panes are drawn
// here. Each takes its color from the text around it.
import type { JSX } from 'solid-js';

type IconProps = { size?: number; class?: string };

function Stroke(props: IconProps & { children: JSX.Element }) {
  return (
    <svg
      class={props.class}
      width={props.size ?? 20}
      height={props.size ?? 20}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="1.75"
      stroke-linecap="round"
      stroke-linejoin="round"
      aria-hidden="true"
    >
      {props.children}
    </svg>
  );
}

function Mark(props: IconProps & { d: string }) {
  return (
    <svg
      class={props.class}
      width={props.size ?? 20}
      height={props.size ?? 20}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
    >
      <path d={props.d} />
    </svg>
  );
}

